<script lang="ts">
import {onDestroy} from 'svelte';import {notificationAction} from './bridge';import {notificationError,type NotificationDraft,type Recipient} from './notifications';import Icon from './Icon.svelte';import Choice from './Choice.svelte';import NotificationEvents from './NotificationEvents.svelte';import RecipientDialog from './RecipientDialog.svelte';import WebhookDialog from './WebhookDialog.svelte';
let {draft=$bindable(),t,profile,province,language,onchange}:{draft:NotificationDraft;t:(key:string)=>string;profile:string;province:string;language:string;onchange:()=>void}=$props();
let reveal=$state(false);let help=$state(false);let verify=$state('idle');let bot=$state('');let botDetail=$state('');let recipientDialog=$state(false);let webhookDialog=$state(false);let webhookTest=$state('idle');let webhookDetail=$state('');let tests=$state<Record<string,string>>({});let details=$state<Record<string,string>>({});let alive=true;onDestroy(()=>alive=false);
async function check(){verify='busy';const token=draft.telegram.token.trim();try{const value=await notificationAction<{username:string}>({action:'check_bot',token});if(alive&&draft.telegram.token.trim()===token){bot='@'+value.username;verify='ok';botDetail='';}}catch(reason){if(alive&&draft.telegram.token.trim()===token){verify='error';botDetail=notificationError(reason,t);}}}
function add(recipient:Recipient){if(!draft.telegram.recipients.some(r=>r.id===recipient.id)){draft.telegram.recipients=[...draft.telegram.recipients,recipient];onchange();}recipientDialog=false;}
async function testRecipient(recipient:Recipient){tests[recipient.id]='busy';try{const result=await notificationAction<{elapsed_ms:number}>({action:'telegram_test',token:draft.telegram.token.trim(),chat_id:recipient.id,profile,province,language});if(alive){tests[recipient.id]='ok';details[recipient.id]=`${t('Выполнено')} · ${result.elapsed_ms} ms`;}}catch(reason){if(alive){tests[recipient.id]='error';details[recipient.id]=notificationError(reason,t);}}}
async function testWebhook(){webhookTest='busy';try{const result=await notificationAction<{status:number;elapsed_ms:number}>({action:'webhook_test',config:$state.snapshot(draft.webhook.config),profile,province,language});if(alive){webhookTest='ok';webhookDetail=`HTTP ${result.status} · ${result.elapsed_ms} ms`;}}catch(reason){if(alive){webhookTest='error';webhookDetail=notificationError(reason,t);}}}
</script>
<div class="notification-panel"><div class="channel-heading"><h2>Telegram</h2><button type="button" class="switch" role="switch" aria-label="Telegram" aria-checked={draft.telegram.enabled} onclick={()=>{draft.telegram.enabled=!draft.telegram.enabled;onchange();}}><span></span></button></div>
{#if draft.telegram.enabled}<div class="channel-body"><div class="token-row"><div class="profile-field"><Icon name="key"/><label><small>{t('Токен бота')}</small><input aria-label={t('Токен бота')} type={reveal?'text':'password'} bind:value={draft.telegram.token} oninput={()=>{verify='idle';bot='';botDetail='';onchange();}} autocomplete="off" spellcheck="false" maxlength="256"/></label><button type="button" class="icon-button" aria-label={t('Показать значение')} aria-pressed={reveal} onclick={()=>reveal=!reveal}><Icon name="eye" size={18}/></button></div><button type="button" disabled={verify==='busy'||!draft.telegram.token.trim()} title={botDetail||t('Проверить')} onclick={()=>void check()}><Icon name={verify==='busy'?'clock':verify==='error'?'alert':'check'}/>{t('Проверить')}</button></div>
<div class="bot-help-row"><button type="button" class="disclosure" aria-expanded={help} onclick={()=>help=!help}>{help?'▾':'▸'} {t('Как получить токен')}</button><small class="muted" title={botDetail}>{bot||botDetail}</small></div>{#if help}<small class="muted">{t('Открыть @BotFather в Telegram → /newbot → задать имя бота → скопировать токен.')}</small>{/if}
<div class="parameter-heading"><span class="muted">{t('Получатели')}</span><button type="button" class="icon-button" disabled={!draft.telegram.token.trim()||draft.telegram.recipients.length>=32} title={t('Добавить получателя')} aria-label={t('Добавить получателя')} onclick={()=>recipientDialog=true}><Icon name="plus"/></button></div><div class="recipient-list">{#each draft.telegram.recipients as recipient}<div class="recipient-row"><Icon name={recipient.type==='private'?'user':'office'} size={17}/><span><strong>{recipient.label}</strong><small class="muted">{recipient.id}</small></span><button type="button" class="icon-button" disabled={tests[recipient.id]==='busy'} title={details[recipient.id]||t('Тестовое сообщение')} aria-label={t('Тестовое сообщение')+' · '+recipient.label} onclick={()=>void testRecipient(recipient)}><Icon name={tests[recipient.id]==='ok'?'check':tests[recipient.id]==='error'?'alert':tests[recipient.id]==='busy'?'clock':'send'} size={18}/></button><button type="button" class="icon-button" title={t('Удалить получателя')} aria-label={t('Удалить получателя')+' · '+recipient.label} onclick={()=>{draft.telegram.recipients=draft.telegram.recipients.filter(r=>r.id!==recipient.id);onchange();}}><Icon name="trash" size={18}/></button></div>{:else}<small class="muted recipient-empty">{t('Добавить получателя кнопкой «+».')}</small>{/each}</div><NotificationEvents bind:values={draft.telegram.events} {t} {onchange}/></div>{/if}
<div class="channel-heading webhook-heading"><h2>Webhook</h2><button type="button" class="switch" role="switch" aria-label="Webhook" aria-checked={draft.webhook.enabled} onclick={()=>{draft.webhook.enabled=!draft.webhook.enabled;onchange();}}><span></span></button></div>
{#if draft.webhook.enabled}<div class="channel-body"><div class="webhook-url-row"><label class="profile-field"><Icon name="external"/><span><small>{t('URL получателя')}</small><input type="url" aria-label={t('URL получателя')} bind:value={draft.webhook.config.url} oninput={onchange} autocomplete="off" spellcheck="false" maxlength="4096"/></span></label><div class="webhook-method"><Choice label={t('Метод')} icon={null} bind:value={draft.webhook.config.method} options={[{value:'POST',label:'POST'},{value:'GET',label:'GET'}]} {onchange}/></div></div><small class="muted method-hint">{t(draft.webhook.config.method==='GET'?'Без тела запроса. Данные передаются параметрами URL.':'Событие отправляется в теле запроса в формате JSON.')}</small><button type="button" class="flat-action" onclick={()=>webhookDialog=true}><Icon name="settings" size={18}/>{t('Дополнительные параметры')}</button><NotificationEvents bind:values={draft.webhook.events} {t} {onchange}/><button type="button" class="notification-test" disabled={webhookTest==='busy'||!draft.webhook.config.url.trim()} title={webhookDetail||t('Тест')} onclick={()=>void testWebhook()}><Icon name={webhookTest==='ok'?'check':webhookTest==='error'?'alert':webhookTest==='busy'?'clock':'test'}/>{t('Тест')}</button></div>{/if}</div>
{#if recipientDialog}<RecipientDialog token={draft.telegram.token.trim()} {t} onclose={()=>recipientDialog=false} onadd={add}/>{/if}
{#if webhookDialog}<WebhookDialog config={draft.webhook.config} {t} {profile} {province} {language} onclose={()=>webhookDialog=false} ondone={value=>{draft.webhook.config=value;onchange();webhookDialog=false;}}/>{/if}
